export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tTop = u / g;
  const yTop = (u * u) / (2 * g);

  const t = Math.max(0, Math.min(time, 2 * tTop));
  const y = u * t - 0.5 * g * t * t;
  const v = u - g * t;
  const a = -g;
  const Fg = m * g;

  let motionState = "Ready to toss";
  if (t > 0 && t < tTop - 0.05) motionState = "Rising";
  else if (Math.abs(t - tTop) <= 0.05) motionState = "At the top";
  else if (t > tTop + 0.05 && y > 0) motionState = "Falling";
  else if (y <= 0 && t > 0) motionState = "Back at launch height";

  const objects = [];

  // Lanes
  objects.push(...sdk.panel({ x: 20, y: 35, w: 280, h: 330, title: "Motion", state: motionState, id: "lane.motion" }));
  objects.push(...sdk.panel({ x: 320, y: 35, w: 300, h: 330, title: "Velocity over time", state: `t = ${sdk.format(t, 2)} s`, id: "lane.plot" }));

  // Left panel content: Height ruler and ball
  objects.push(sdk.axis("axis.height", { x: 50, y: 70, length: 280, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));

  const ballYCoord = 350 - (y / 2.2) * 280;
  objects.push(sdk.circle("ball.toss", 140, ballYCoord, 24, { role: "output" }));

  // Vectors
  objects.push(...sdk.vector("vec.v", { x: 170, y: ballYCoord }, { value: v, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a", { x: 195, y: ballYCoord }, { value: a, direction: "up" }, { scale: 15, label: "a" }));

  // Callout
  const calloutLines = [
    `v: ${sdk.format(v, 2)} m/s`,
    `a: ${sdk.format(a, 2)} m/s^2`,
    `Fg: ${sdk.format(Fg, 1)} N`
  ];
  objects.push(...sdk.callout(220, ballYCoord - 25, calloutLines, { id: "callout.toss" }));

  // Right panel content: Plot v-t
  const dtPoints = [];
  const maxT = 2 * tTop;
  const steps = 20;
  for (let i = 0; i <= steps; i++) {
    const pt = (i / steps) * maxT;
    const pv = u - g * pt;
    dtPoints.push([pt, pv]);
  }

  const activePoints = [];
  for (let i = 0; i <= steps; i++) {
    const pt = (i / steps) * maxT;
    if (pt <= t) {
      const pv = u - g * pt;
      activePoints.push([pt, pv]);
    }
  }

  objects.push(sdk.plot("plot.vt", {
    x: 340,
    y: 70,
    w: 265,
    h: 240,
    axes: {
      x: { label: "Time", min: 0, max: Math.max(1.8, maxT), unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      { label: "v(t)", kind: "line", points: dtPoints.map(p => ({ x: p[0], y: p[1] })) },
      { label: "active", kind: "line", points: activePoints.map(p => ({ x: p[0], y: p[1] })) }
    ]
  }));

  objects.push(sdk.text("plot.vt.note", 340, 325, "Slope a = -g", { align: "start" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: Number(v.toFixed(2)) },
        { id: "acceleration", value: Number(a.toFixed(2)) },
        { id: "force", value: Number(Fg.toFixed(2)) },
        { id: "motionState", value: motionState }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tTop,
      apexHeight: yTop,
      height: y,
      velocity: v,
      acceleration: a,
      force: Fg
    }
  };
}
